package com.ricozknow.rag;
import com.ricozknow.common.TenantContext; import com.ricozknow.rag.dto.*; import com.ricozknow.rag.evaluation.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor
public class RagEvaluationService {
 private final RagEvalCaseRepository caseRepository; private final RagEvalRunRepository runRepository; private final RagRetrievalService retrieval;
 public RagEvalCase create(RagEvalCaseRequest r){ RagEvalCase c=new RagEvalCase(); c.setId(UUID.randomUUID()); c.setTenantId(TenantContext.get()); c.setQuestion(r.question()); c.setExpectedArticleIds(r.expectedArticleIds()==null?"":r.expectedArticleIds().stream().map(UUID::toString).collect(Collectors.joining(","))); c.setExpectedAnswer(r.expectedAnswer()); c.setEnabled(r.enabled()==null||r.enabled()); c.setCreatedAt(Instant.now()); return caseRepository.save(c); }
 public RagEvalRunResponse run(){ UUID tenant=TenantContext.get(); List<RagEvalCase> cases=caseRepository.findByTenantIdAndEnabledTrue(tenant); RagEvalRun run=new RagEvalRun(); run.setId(UUID.randomUUID());run.setTenantId(tenant);run.setStartedAt(Instant.now()); int hits=0; double mrr=0; long totalLatency=0; int count=0; for(RagEvalCase c:cases){ long s=System.nanoTime(); RagSearchResponse res=retrieval.retrieve(new RagSearchRequest(c.getQuestion(),10,null,null,null,null,null)); long latency=(System.nanoTime()-s)/1_000_000; totalLatency+=latency;count++; Set<String> expected=Arrays.stream(c.getExpectedArticleIds().split(",")).filter(x->!x.isBlank()).collect(Collectors.toSet()); int rank=1; boolean found=false; for(RagSearchResponse.RagSearchResult x:res.results()){if(x.articleId()!=null && expected.contains(x.articleId().toString())){found=true; mrr+=1.0/rank;break;}rank++;} if(found)hits++; }
 run.setCompletedAt(Instant.now());run.setCaseCount(count);run.setHitAtK(count==0?0:(double)hits/count);run.setMrr(count==0?0:mrr/count);run.setAvgLatencyMs(count==0?0:(double)totalLatency/count);runRepository.save(run); return new RagEvalRunResponse(run.getId(),count,run.getHitAtK(),run.getMrr(),run.getAvgLatencyMs()); }
 public List<RagEvalRun> recent(){return runRepository.findTop20ByTenantIdOrderByStartedAtDesc(TenantContext.get());}
}
